8d4d5cb98caf07656d288bc1cbf0", "excerpt_id": "excerpt:9d521fc02aa4498e:codec.py:27-52", "span": "27-52"}, {"id": "excerpt:9d521fc02aa4498e:codec.py:55-57", "scope_id": "fixture-shop", "release_id": "release:cart:9d521fc02aa4498e", "kind": "code", "path": "codec.py", "line_start": 55, "line_end": 57, "text": "def health(data: bytes = b\"\") -> dict:\n    \"\"\"Startup/readiness check: the build loads and answers. Reads no retained state.\"\"\"\n    return {\"status\": \"ok\", \"service\": \"cart\", \"version\": \"1.5\"}", "content_hash": "sha256:da1678e0a98fe1de2fb1a2bacc00f70e3fc40d4a642ebb8c409165cd60fbe849", "excerpt_id": "excerpt:9d521fc02aa4498e:codec.py:55-57", "span": "55-57"}]}, {"release_id": "release:checkout:fdc1261d7c96078e", "service": "checkout", "version": "2.0", "artifact_hash": "sha256:fdc1261d7c96078ef5866f4197862a43472ebc032b8745a6d0e0842ca9c87e86", "declared_flags": [], "excerpts": [{"id": "excerpt:fdc1261d7c96078e:CHANGELOG.md:5-5", "scope_id": "fixture-shop", "release_id": "release:checkout:fdc1261d7c96078e", "kind": "changelog", "path": "CHANGELOG.md", "line_start": 5, "line_end": 5, "text": "- Checkout prices saved carts read from cart-cache; receipts computed per line.", "content_hash": "sha256:e4610fff12436ed1ac0ad3b3af26691a8d8f78dd059277daba8dc1e6868e56ae", "excerpt_id": "excerpt:fdc1261d7c96078e:CHANGELOG.md:5-5", "span": "5-5"}, {"id": "excerpt:fdc1261d7c96078e:codec.py:8-16", "scope_id": "fixture-shop", "release_id": "release:checkout:fdc1261d7c96078e", "kind": "code", "path": "codec.py", "line_start": 8, "line_end": 16, "text": "def read_cart_for_pricing(data: bytes) -> dict:\n    \"\"\"Read a saved cart for pricing; cart/v1 only.\"\"\"\n    obj = json.loads(data)\n    if obj.get(\"fmt\") != FMT:\n        raise ValueError(f\"unsupported saved-cart format {obj.get('fmt')!r}\")\n    items = obj.get(\"items\")\n    if not isinstance(items, list):\n        raise ValueError(\"cart/v1 requires an items list\")\n    return {\"format\": FMT, \"priced_lines\": len(items)}", "content_hash": "sha256:1a2c938ff7b86db12f9b19638b5c1f6ed7fa0d65ac1615be9a36379853835fe0", "excerpt_id": "excerpt:fdc1261d7c96078e:codec.py:8-16", "span": "8-16"}, {"id": "excerpt:fdc1261d7c96078e:codec.py:19-24", "scope_id": "fixture-shop", "release_id": "release:checkout:fdc1261d7c96078e", "kind": "code", "path": "codec.py", "line_start": 19, "line_end": 24, "text": "def receipt_total(lines: list) -> int:\n    \"\"\"Cents; rounds each line then sums (pre-INC-4471 behaviour).\"\"\"\n    total = 0\n    for line in lines:\n        total += int(round(line[\"price_cents\"] * line[\"qty\"]))\n    return total", "content_hash": "sha256:21d36c125d48873e7155f5798142594e6f99c4896d1a201ab6fcc88eb9dccac8", "excerpt_id": "excerpt:fdc1261d7c96078e:codec.py:19-24", "span": "19-24"}, {"id": "excerpt:fdc1261d7c96078e:codec.py:27-29", "scope_id": "fixture-shop", "release_id": "release:checkout:fdc1261d7c96078e", "kind": "code", "path": "codec.py", "line_start": 27, "line_end": 29, "text": "def health(data: bytes = b\"\") -> dict:\n    \"\"\"Startup/readiness check: the build loads and answers. Reads no retained state.\"\"\"\n    return {\"status\": \"ok\", \"service\": \"checkout\", \"version\": \"2.0\"}", "content_hash": "sha256:37dafd98583f3882d429c50f728d5a25e600ea3cdb18efb105265fce59f6c735", "excerpt_id": "excerpt:fdc1261d7c96078e:codec.py:27-29", "span": "27-29"}]}, {"release_id": "release:checkout:df9a7917d5945176", "service": "checkout", "version": "2.1", "artifact_hash": "sha256:df9a7917d594517630ca6aeb0b8e97b663e387769371b3658348ad483b142e02", "declared_flags": [], "excerpts": [{"id": "excerpt:df9a7917d5945176:CHANGELOG.md:5-5", "scope_id": "fixture-shop", "release_id": "release:checkout:df9a7917d5945176", "kind": "changelog", "path": "CHANGELOG.md", "line_start": 5, "line_end": 5, "text": "- Receipt correction: receipt totals are now computed from unrounded line amounts and rounded once, fixing 1-cent receipt mismatches (INC-4471).", "content_hash": "sha256:10bd0794e4f77df03d94d718b3340eecb3b443ed76901900f5fb2b953647d043", "excerpt_id": "excerpt:df9a7917d5945176:CHANGELOG.md:5-5", "span": "5-5"}, {"id": "excerpt:df9a7917d5945176:CHANGELOG.md:6-6", "scope_id": "fixture-shop", "release_id": "release:checkout:df9a7917d5945176", "kind": "changelog", "path": "CHANGELOG.md", "line_start": 6, "line_end": 6, "text": "- Basket rollout support: the order summary shows basket headings when a saved cart has baskets; pricing reads cart/v1 and cart/v2.", "content_hash": "sha256:20dc649c5c0dcce8319e354e5b492f26940730a09b7050161fe64588498154ce", "excerpt_id": "excerpt:df9a7917d5945176:CHANGELOG.md:6-6", "span": "6-6"}, {"id": "excerpt:df9a7917d5945176:CHANGELOG.md:7-7", "scope_id": "fixture-shop", "release_id": "release:checkout:df9a7917d5945176", "kind": "changelog", "path": "CHANGELOG.md", "line_start": 7, "line_end": 7, "text": "- Shipped in bundle rollout-2026-10-basket together with cart 1.5.", "content_hash": "sha256:5c09985fef5f5b285761b2ede818873a75e5ea01644972e61180cee5ac972682", "excerpt_id": "excerpt:df9a7917d5945176:CHANGELOG.md:7-7", "span": "7-7"}, {"id": "excerpt:df9a7917d5945176:codec.py:9-21", "scope_id": "fixture-shop", "release_id": "release:checkout:df9a7917d5945176", "kind": "code", "path": "codec.py", "line_start": 9, "line_end": 21, "text": "def read_cart_for_pricing(data: bytes) -> dict:\n    \"\"\"Read a saved cart for pricing; accepts cart/v1 and cart/v2.\"\"\"\n    obj = json.loads(data)\n    fmt = obj.get(\"fmt\")\n    if fmt == FMT_V1:\n        lines = obj.get(\"items\")\n    elif fmt == FMT_V2:\n        lines = obj.get(\"lines\")\n    else:\n        raise ValueError(f\"unsupported saved-cart format {fmt!r}\")\n    if not isinstance(lines, list):\n        raise ValueError(f\"{fmt} requires a list of lines\")\n    return {\"format\": fmt, \"priced_lines\": len(lines)}", "content_hash": "sha256:28feb338e11d0c40ae33380b05e8c379211aac6b9d753b25e11de3e14b757d86", "excerpt_id": "excerpt:df9a7917d5945176:codec.py:9-21", "span": "9-21"}, {"id": "excerpt:df9a7917d5945176:codec.py:24-26", "scope_id": "fixture-shop", "release_id": "release:checkout:df9a7917d5945176", "kind": "code", "path": "codec.py", "line_start": 24, "line_end": 26, "text": "def receipt_total(lines: list) -> int:\n    \"\"\"Cents; sums unrounded line amounts and rounds once (INC-4471 fix).\"\"\"\n    return int(round(sum(line[\"price_cents\"] * line[\"qty\"] for line in lines)))", "content_hash": "sha256:ebbd045660e32e51dd5677554dfa2e6fb2df1b2edec40ac120e962415c5e3e2a", "excerpt_id": "excerpt:df9a7917d5945176:codec.py:24-26", "span": "24-26"}, {"id": "excerpt:df9a7917d5945176:codec.py:29-31", "scope_id": "fixture-shop", "release_id": "release:checkout:df9a7917d5945176", "kind": "code", "path": "codec.py", "line_start": 29, "line_end": 31, "text": "def health(data: bytes = b\"\") -> dict:\n    \"\"\"Startup/readiness check: the build loads and answers. Reads no retained state.\"\"\"\n    return {\"status\": \"ok\", \"service\": \"checkout\", \"version\": \"2.1\"}", "content_hash": "sha256:f34f859dfb56338f4228c0b4f9c1abbd1546c4079cbf0ed66456f3465ad98a62", "excerpt_id": "excerpt:df9a7917d5945176:codec.py:29-31", "span": "29-31"}]}], "baseline": [{"flags": {"basket_v2": true}, "service": "cart", "version": "1.5", "release_id": "release:cart:9d521fc02aa4498e"}, {"flags": {}, "service": "checkout", "version": "2.1", "release_id": "release:checkout:df9a7917d5945176"}]}
